insert into public.companies (slug, name, industry, size, hq, about) values
  ('jobs-territory', 'Jobs Territory', 'HR technology', '51-200', 'Coimbatore', 'Builds the CRM and applicant tracking system used by staffing agencies across South India. Interns and fresh graduates work directly with the product and recruiting teams from week one.'),
  ('indus-ledger', 'Indus Ledger', 'Fintech', '201-500', 'Bengaluru', 'Digital lending platform that approves small-business loans in under a day. Engineering, risk and design sit in one product team per loan type.'),
  ('tamarind-health', 'Tamarind Health', 'Healthcare technology', '201-500', 'Chennai', 'Appointment, records and teleconsultation software for 1,400 clinics. The product has to work on slow networks and old Android phones.'),
  ('brightwell-labs', 'Brightwell Labs', 'Developer tools', '51-200', 'Pune', 'Makes build and release tooling for small engineering teams. Fully distributed, writes everything down, and ships weekly.'),
  ('orchard-cloud', 'Orchard Cloud', 'Cloud infrastructure', '501-1000', 'Hyderabad', 'Managed hosting and platform engineering for mid-sized companies moving off their own data centres.'),
  ('meridian-freight', 'Meridian Freight', 'Logistics', '1001-5000', 'Mumbai', 'Road and rail freight network with 220 depots. Runs on spreadsheets that the data team is steadily replacing.'),
  ('lattice-robotics', 'Lattice Robotics', 'Robotics', '51-200', 'Bengaluru', 'Warehouse picking robots, built and tested in-house. Software, hardware and operations share one floor.'),
  ('fernhill-analytics', 'Fernhill Analytics', 'Data and analytics', '201-500', 'London', 'Analytics consultancy and software for retail and energy clients. Small teams, long engagements, and a strong writing culture.'),
  ('quayside-payments', 'Quayside Payments', 'Payments', '501-1000', 'Dublin', 'Card acquiring and instant payouts for online marketplaces across Europe.'),
  ('parallax-games', 'Parallax Games', 'Gaming', '51-200', 'Singapore', 'Mobile strategy games with a live-ops team of about 40. Two titles in the top 100 in Southeast Asia.'),
  ('koel-learning', 'Koel Learning', 'Education technology', '201-500', 'Delhi', 'Test preparation and spoken-English courses delivered mostly on phones, for learners in tier 2 and tier 3 cities.'),
  ('greenfield-energy', 'Greenfield Energy', 'Renewable energy', '1001-5000', 'Coimbatore', 'Develops and operates rooftop and ground-mounted solar plants across Tamil Nadu and Karnataka.'),
  ('aster-mobility', 'Aster Mobility', 'Mobility', '501-1000', 'Gurugram', 'Electric scooter rentals and a charging network in 11 cities.'),
  ('halcyon-design', 'Halcyon Design Co.', 'Design studio', '11-50', 'Mumbai', 'Product design studio working with healthcare and finance clients. Prefers fewer projects, done properly.'),
  ('northgate-security', 'Northgate Security', 'Cybersecurity', '201-500', 'Toronto', 'Managed detection and response for banks and credit unions, with a 24x7 operations centre.'),
  ('basil-commerce', 'Basil & Co.', 'E-commerce', '201-500', 'Kochi', 'Online marketplace for spices, handloom and home goods from small producers in Kerala.'),
  ('vantage-retail', 'Vantage Retail Systems', 'Retail technology', '1001-5000', 'Austin', 'Point-of-sale, inventory and loyalty software used in 9,000 stores across North America.');
insert into public.jobs (slug, company_id, title, location, work_mode, job_type, level, salary_min, salary_max, currency, summary, responsibilities, requirements, skills, posted_at, closes_at) values
  ('software-engineering-intern-wfo', (select id from public.companies where slug = 'jobs-territory'), 'Software Engineering Intern (Work from Office)', 'Coimbatore', 'onsite', 'internship', 'intern', 216000, 324000, 'INR', 'Six-month on-site internship in the Coimbatore office, building features on the ATS the recruiting team uses every day. You will pair with a mentor and ship to production within your first month.', array['Build and fix small features in the candidate and recruiter web apps', 'Write SQL queries and API endpoints with review from a senior engineer', 'Add tests for the code you change', 'Present what you shipped at the monthly demo']::text[], array['Final-year or recently graduated B.E., B.Tech, BCA or MCA student', 'Comfortable with JavaScript and one backend framework', 'You have built at least one project and can explain how it works', 'Able to work from the Coimbatore office five days a week']::text[], array['JavaScript', 'Node.js', 'SQL', 'Git', 'REST APIs']::text[], now() - interval '5 hours', now() + interval '21 days'),
  ('hr-operations-intern-wfo', (select id from public.companies where slug = 'jobs-territory'), 'HR Operations Intern (Work from Office)', 'Coimbatore', 'onsite', 'internship', 'intern', 168000, 216000, 'INR', 'On-site internship supporting the recruiting operations team: scheduling interviews, keeping candidate records accurate and following up with applicants.', array['Schedule interviews and send confirmations to candidates', 'Keep candidate records in the ATS up to date', 'Prepare weekly pipeline reports in Excel', 'Answer candidate questions by phone and email']::text[], array['Pursuing or completed MBA, BBA or a related degree', 'Clear spoken and written English and Tamil', 'Working knowledge of Excel', 'Able to work from the Coimbatore office five days a week']::text[], array['Communication', 'Excel', 'Recruitment', 'ATS']::text[], now() - interval '29 hours', now() + interval '14 days'),
  ('talent-acquisition-specialist', (select id from public.companies where slug = 'jobs-territory'), 'Talent Acquisition Specialist', 'Coimbatore', 'onsite', 'full_time', 'junior', 384000, 612000, 'INR', 'Own hiring for the engineering and sales teams: source candidates, run first-round screens and keep hiring managers informed.', array['Source candidates on job boards and professional networks', 'Run 20 to 30 screening calls a week', 'Coordinate interview loops with hiring managers', 'Report pipeline health every Friday']::text[], array['1 to 3 years in recruitment or talent acquisition', 'Comfortable screening technical and non-technical candidates', 'Experience with an applicant tracking system', 'Fluent in English; Tamil is a plus']::text[], array['Sourcing', 'Interviewing', 'ATS', 'Communication']::text[], now() - interval '52 hours', now() + interval '30 days'),
  ('full-stack-engineer-ats', (select id from public.companies where slug = 'jobs-territory'), 'Full Stack Engineer, ATS Platform', 'Coimbatore', 'hybrid', 'full_time', 'mid', 1380000, 1960000, 'INR', 'Work on the applicant tracking system used by 300 recruiters. Current focus: candidate matching, bulk actions and an API for customers who integrate their own tools.', array['Design and build features end to end, from schema to UI', 'Improve search and filtering performance on tables with millions of rows', 'Review pull requests and mentor interns', 'Take part in a weekly on-call rotation']::text[], array['3 to 6 years building web applications', 'Strong TypeScript, React and a SQL database', 'You have debugged a slow query in production', 'Clear written communication']::text[], array['React', 'TypeScript', 'Node.js', 'PostgreSQL', 'REST APIs']::text[], now() - interval '71 hours', now() + interval '45 days'),
  ('backend-engineer-lending', (select id from public.companies where slug = 'indus-ledger'), 'Backend Engineer, Lending', 'Bengaluru', 'hybrid', 'full_time', 'mid', 2140000, 3120000, 'INR', 'Build the services behind loan origination and repayment: eligibility checks, disbursal, and reconciliation with partner banks. Correctness matters more than speed here.', array['Own services that move money and must never double-post', 'Design idempotent APIs and reconciliation jobs', 'Investigate production incidents and write the follow-up', 'Work with risk analysts on new underwriting rules']::text[], array['3+ years of backend development', 'Solid PostgreSQL: transactions, indexes, locking', 'Experience with message queues such as Kafka', 'Care about tests and rollout safety']::text[], array['Python', 'PostgreSQL', 'Kafka', 'Docker', 'REST APIs']::text[], now() - interval '7 hours', now() + interval '18 days'),
  ('senior-product-designer', (select id from public.companies where slug = 'indus-ledger'), 'Senior Product Designer', 'Bengaluru', 'hybrid', 'full_time', 'senior', 2840000, 3960000, 'INR', 'Lead design for the small-business onboarding flow, where roughly one in three applicants currently drops off. You will research, prototype and test with real applicants.', array['Run interviews and usability tests with loan applicants', 'Design flows for web and Android, in Hindi and English', 'Extend the design system with the front-end team', 'Present trade-offs to the product and risk leads']::text[], array['6+ years in product design with shipped work to show', 'Experience with regulated or form-heavy products', 'Comfortable in Figma and with prototyping', 'Able to write clear rationale for design decisions']::text[], array['Figma', 'Design Systems', 'User Research', 'Prototyping']::text[], now() - interval '51 hours', now() + interval '12 days'),
  ('data-analyst-credit-risk', (select id from public.companies where slug = 'indus-ledger'), 'Data Analyst, Credit Risk', 'Bengaluru', 'onsite', 'full_time', 'junior', 780000, 1160000, 'INR', 'Analyse repayment behaviour and help the risk team tune lending rules. You will own the weekly portfolio report that leadership reads on Monday.', array['Write SQL to track delinquency by cohort', 'Build and maintain the weekly portfolio dashboard', 'Back-test proposed rule changes', 'Explain findings to non-technical colleagues']::text[], array['1 to 3 years in analytics', 'Strong SQL and basic statistics', 'Python or R for analysis', 'Interest in credit and lending']::text[], array['SQL', 'Python', 'Excel', 'Power BI', 'Statistics']::text[], now() - interval '99 hours', now() + interval '25 days'),
  ('frontend-engineer-patient-app', (select id from public.companies where slug = 'tamarind-health'), 'Frontend Engineer, Patient App', 'Chennai', 'hybrid', 'full_time', 'mid', 1420000, 2080000, 'INR', 'Build the patient-facing web app that books appointments and shows lab results. Many users are on low-end phones, so performance and accessibility are part of the job.', array['Build accessible, fast interfaces for booking and records', 'Keep the bundle small and test on low-end Android devices', 'Write component and end-to-end tests', 'Work with designers on content in Tamil, Hindi and English']::text[], array['3+ years of React and TypeScript', 'Working knowledge of WCAG and screen readers', 'Experience measuring and improving web performance', 'Familiarity with GraphQL']::text[], array['React', 'TypeScript', 'Accessibility', 'Testing', 'GraphQL']::text[], now() - interval '13 hours', now() + interval '9 days'),
  ('clinical-operations-coordinator', (select id from public.companies where slug = 'tamarind-health'), 'Clinical Operations Coordinator', 'Chennai', 'onsite', 'full_time', 'junior', 420000, 560000, 'INR', 'Help new partner clinics get set up on the platform: training their front desk, fixing scheduling issues and collecting feedback for the product team.', array['Train clinic staff on the scheduling and records tools', 'Resolve onboarding issues within one working day', 'Document recurring problems for the product team', 'Visit partner clinics in Chennai twice a week']::text[], array['Graduate in any discipline, healthcare background helpful', 'Patient and clear communicator', 'Comfortable with spreadsheets', 'Willing to travel locally']::text[], array['Communication', 'Excel', 'Scheduling', 'Documentation']::text[], now() - interval '140 hours', now() + interval '7 days'),
  ('qa-automation-engineer', (select id from public.companies where slug = 'tamarind-health'), 'QA Automation Engineer', 'Chennai', 'hybrid', 'full_time', 'mid', 1120000, 1680000, 'INR', 'Own automated testing for appointment booking and payments. You will decide what is worth automating and keep the suite fast enough that people run it.', array['Maintain a browser and API test suite running on every pull request', 'Reduce flaky tests and track suite runtime', 'Pair with engineers to test new features early', 'Report release risk in plain language']::text[], array['3+ years in QA with automation experience', 'Playwright or Cypress in a real project', 'Good understanding of REST APIs', 'Experience in CI pipelines']::text[], array['Playwright', 'Cypress', 'JavaScript', 'API Testing', 'CI/CD']::text[], now() - interval '38 hours', now() + interval '20 days'),
  ('developer-advocate', (select id from public.companies where slug = 'brightwell-labs'), 'Developer Advocate', 'Pune', 'remote', 'full_time', 'mid', 1860000, 2740000, 'INR', 'Be the voice of Brightwell with developers: write tutorials, give talks, answer questions in the community forum and bring what you hear back to the product team.', array['Publish two long-form tutorials a month', 'Give talks at meetups and conferences', 'Answer community questions and triage feedback', 'Build sample projects that show real workflows']::text[], array['3+ years as a developer, writer or advocate', 'Public examples of your writing or talks', 'Fluent English and strong JavaScript', 'Comfortable working across time zones']::text[], array['Technical Writing', 'JavaScript', 'Public Speaking', 'Community', 'Git']::text[], now() - interval '76 hours', now() + interval '40 days'),
  ('software-engineer-cli-tools', (select id from public.companies where slug = 'brightwell-labs'), 'Software Engineer, CLI Tools', 'Pune', 'remote', 'full_time', 'senior', 2640000, 3680000, 'INR', 'Maintain the command-line tool that 60,000 developers run in their build pipelines. Backwards compatibility and clear error messages are the product.', array['Design and ship new commands with careful deprecation paths', 'Profile and speed up cold-start time', 'Review community pull requests', 'Write release notes and migration guides']::text[], array['5+ years of professional programming, Go preferred', 'Experience shipping developer-facing tools', 'Comfortable on Linux and macOS', 'Meticulous about edge cases']::text[], array['Go', 'Linux', 'Git', 'Testing', 'APIs']::text[], now() - interval '190 hours', now() + interval '35 days'),
  ('frontend-developer-intern-brightwell', (select id from public.companies where slug = 'brightwell-labs'), 'Frontend Developer Intern', 'Pune', 'hybrid', 'internship', 'intern', 240000, 336000, 'INR', 'Four-month internship on the dashboard team, working on real tickets alongside two engineers. Hybrid, three days a week in the Pune office.', array['Fix interface bugs and ship small features', 'Write unit tests for components', 'Improve loading and empty states', 'Share what you learned in a short write-up']::text[], array['Studying or recently completed an engineering degree', 'Built a React project you can show', 'Understand CSS layout', 'Willing to be in Pune three days a week']::text[], array['React', 'JavaScript', 'CSS', 'Git']::text[], now() - interval '27 hours', now() + interval '16 days'),
  ('site-reliability-engineer', (select id from public.companies where slug = 'orchard-cloud'), 'Site Reliability Engineer', 'Hyderabad', 'hybrid', 'full_time', 'senior', 3120000, 4380000, 'INR', 'Keep customer workloads running across 40 clusters. You will define service level objectives with customers and automate the toil out of on-call.', array['Run and improve Kubernetes clusters on AWS', 'Define SLOs and alerts that wake people only when needed', 'Lead incident reviews without blame', 'Automate repetitive operational tasks with Terraform and scripts']::text[], array['5+ years in SRE, DevOps or infrastructure', 'Deep Kubernetes and Linux knowledge', 'Experience being on call for production systems', 'Good at writing postmortems']::text[], array['Kubernetes', 'Terraform', 'AWS', 'Linux', 'Prometheus']::text[], now() - interval '9 hours', now() + interval '22 days'),
  ('cloud-solutions-architect', (select id from public.companies where slug = 'orchard-cloud'), 'Cloud Solutions Architect', 'Hyderabad', 'onsite', 'full_time', 'lead', 4260000, 5840000, 'INR', 'Design migration plans for customers moving from on-premise servers to the cloud. Half your week is with customers, half with the delivery team.', array['Assess customer environments and propose target architectures', 'Estimate effort and cost with the delivery lead', 'Review designs produced by senior engineers', 'Present to customer leadership']::text[], array['8+ years including customer-facing architecture', 'AWS or Azure professional certification', 'Strong networking and security fundamentals', 'Able to explain trade-offs to non-engineers']::text[], array['AWS', 'Azure', 'Terraform', 'Networking', 'Stakeholder Management']::text[], now() - interval '220 hours', now() + interval '50 days'),
  ('technical-support-engineer', (select id from public.companies where slug = 'orchard-cloud'), 'Technical Support Engineer', 'Hyderabad', 'hybrid', 'full_time', 'junior', 560000, 820000, 'INR', 'First point of contact for customers with hosting problems. You will diagnose issues on live servers and escalate to engineering with a clear summary.', array['Handle tickets by email and chat within agreed response times', 'Diagnose problems using logs and the command line', 'Write knowledge-base articles for recurring issues', 'Escalate with reproduction steps']::text[], array['0 to 2 years in support or system administration', 'Comfortable in a Linux shell', 'Clear, polite written English', 'Rotational shifts including some weekends']::text[], array['Linux', 'SQL', 'Troubleshooting', 'Communication', 'APIs']::text[], now() - interval '61 hours', now() + interval '11 days'),
  ('supply-chain-analyst', (select id from public.companies where slug = 'meridian-freight'), 'Supply Chain Analyst', 'Mumbai', 'onsite', 'full_time', 'junior', 640000, 940000, 'INR', 'Analyse delivery times and depot utilisation, and help planners decide where to add trucks. Your first project is replacing the weekly Excel report with a live dashboard.', array['Build dashboards for on-time delivery and depot load', 'Clean and join data from three legacy systems', 'Model the impact of route changes', 'Present findings to regional managers']::text[], array['1 to 3 years in analytics, supply chain or operations', 'Strong Excel; SQL and Power BI preferred', 'Interest in logistics', 'Willing to visit depots']::text[], array['Excel', 'SQL', 'Logistics', 'Power BI']::text[], now() - interval '17 hours', now() + interval '28 days'),
  ('warehouse-operations-manager', (select id from public.companies where slug = 'meridian-freight'), 'Operations Manager, Warehouse', 'Navi Mumbai', 'onsite', 'full_time', 'senior', 1860000, 2620000, 'INR', 'Run a 180-person warehouse handling 12,000 parcels a day. You are accountable for safety, accuracy and on-time dispatch.', array['Manage shift supervisors and daily dispatch targets', 'Drive a lean programme to cut errors and idle time', 'Own safety audits and incident reporting', 'Plan seasonal capacity with the regional head']::text[], array['8+ years in warehouse or distribution operations', 'Experience leading teams of 100+', 'Working knowledge of warehouse management systems', 'Calm under peak-season pressure']::text[], array['Operations', 'Leadership', 'Lean', 'Excel', 'Safety']::text[], now() - interval '300 hours', now() + interval '60 days'),
  ('robotics-software-engineer', (select id from public.companies where slug = 'lattice-robotics'), 'Robotics Software Engineer', 'Bengaluru', 'onsite', 'full_time', 'mid', 2260000, 3340000, 'INR', 'Write the control and motion-planning software for our picking arms and test it on real hardware the same afternoon.', array['Implement motion planning and collision checking in C++', 'Debug issues on the robot with the hardware team', 'Write simulation tests that run in CI', 'Tune grasp success rates using logged data']::text[], array['3+ years of C++ in robotics or embedded systems', 'ROS experience', 'Solid linear algebra', 'Comfortable working on hardware']::text[], array['C++', 'Python', 'ROS', 'Linux', 'Computer Vision']::text[], now() - interval '33 hours', now() + interval '24 days'),
  ('ml-engineer-perception', (select id from public.companies where slug = 'lattice-robotics'), 'Machine Learning Engineer, Perception', 'Bengaluru', 'hybrid', 'full_time', 'senior', 3380000, 4960000, 'INR', 'Own the models that recognise items in cluttered bins. You will improve accuracy on the hardest 5% of picks and ship models to robots safely.', array['Train and evaluate detection and segmentation models', 'Build tooling to find and label failure cases', 'Deploy models to edge devices with rollback', 'Work with the robotics team on latency budgets']::text[], array['5+ years in applied machine learning', 'Production experience with PyTorch', 'Understanding of model evaluation beyond accuracy', 'Comfortable with Docker and CI']::text[], array['Python', 'PyTorch', 'Computer Vision', 'MLOps', 'Docker']::text[], now() - interval '85 hours', now() + interval '33 days'),
  ('analytics-engineer', (select id from public.companies where slug = 'fernhill-analytics'), 'Analytics Engineer', 'London', 'hybrid', 'full_time', 'mid', 58000, 74000, 'GBP', 'Model client data in dbt so analysts can answer questions without waiting for engineers. Two days a week in the London office.', array['Build and test dbt models for retail and energy clients', 'Document data definitions with analysts', 'Review teammates'' SQL', 'Monitor data quality and fix breakages quickly']::text[], array['3+ years in analytics engineering or data engineering', 'Strong SQL and dbt', 'Good written communication', 'Right to work in the UK']::text[], array['SQL', 'dbt', 'Python', 'Data Modeling', 'Git']::text[], now() - interval '24 hours', now() + interval '19 days'),
  ('product-manager-data-products', (select id from public.companies where slug = 'fernhill-analytics'), 'Product Manager, Data Products', 'London', 'hybrid', 'full_time', 'senior', 82000, 102000, 'GBP', 'Own the roadmap for the forecasting tool used by 40 retail clients. You will talk to customers weekly and decide what not to build.', array['Interview customers and turn findings into a roadmap', 'Write clear specifications with engineering', 'Track adoption using product analytics', 'Align sales, support and engineering on priorities']::text[], array['5+ years in product management', 'Comfortable reading SQL and dashboards', 'Experience with B2B or data products', 'Right to work in the UK']::text[], array['Roadmapping', 'Analytics', 'SQL', 'Stakeholder Management']::text[], now() - interval '112 hours', now() + interval '26 days'),
  ('backend-engineer-ledger', (select id from public.companies where slug = 'quayside-payments'), 'Backend Engineer, Ledger', 'Dublin', 'hybrid', 'full_time', 'mid', 68000, 86000, 'EUR', 'Work on the double-entry ledger that records every payment. Strong consistency, audits and very high test coverage are the norm.', array['Extend the ledger service with new account types', 'Make writes idempotent and recoverable', 'Run load tests before major launches', 'Join the on-call rotation after three months']::text[], array['4+ years of backend work, Java preferred', 'Understanding of transactions and consistency', 'Experience with event streaming', 'EU work authorisation']::text[], array['Java', 'PostgreSQL', 'Kafka', 'Distributed Systems', 'Testing']::text[], now() - interval '46 hours', now() + interval '17 days'),
  ('fraud-analyst', (select id from public.companies where slug = 'quayside-payments'), 'Fraud Analyst', 'Dublin', 'onsite', 'full_time', 'junior', 42000, 54000, 'EUR', 'Review flagged transactions, spot new fraud patterns and suggest rule changes to the risk team.', array['Review and decide on flagged transactions', 'Write SQL to investigate suspicious merchant behaviour', 'Propose and back-test new rules', 'Write short case summaries for compliance']::text[], array['1 to 2 years in fraud, risk or analytics', 'Comfortable with SQL', 'Attention to detail', 'EU work authorisation']::text[], array['SQL', 'Python', 'Analytics', 'Risk', 'Communication']::text[], now() - interval '130 hours', now() + interval '15 days'),
  ('gameplay-programmer', (select id from public.companies where slug = 'parallax-games'), 'Gameplay Programmer', 'Singapore', 'onsite', 'full_time', 'mid', 78000, 104000, 'SGD', 'Build battle and progression systems for our next strategy title. Designers will change numbers weekly, so the systems have to be easy to tune.', array['Implement gameplay features in Unity and C#', 'Build tools so designers can tune without code changes', 'Profile and fix frame-rate drops on mid-range phones', 'Playtest with the team every Thursday']::text[], array['3+ years of game development', 'Shipped at least one mobile title', 'Strong C#', 'Singapore work eligibility']::text[], array['C#', 'Unity', 'Git', 'Game Design', 'Performance Profiling']::text[], now() - interval '56 hours', now() + interval '31 days'),
  ('ui-artist-game-ui', (select id from public.companies where slug = 'parallax-games'), 'UI Artist, Game UI', 'Singapore', 'hybrid', 'contract', 'junior', 48000, 62000, 'SGD', 'Twelve-month contract designing menus, icons and event screens for a live mobile game.', array['Design and animate screens for seasonal events', 'Keep the UI style consistent across the game', 'Hand off assets to engineers with clear specs', 'Iterate on feedback from player data']::text[], array['2+ years of UI art for games or apps', 'Portfolio with shipped screens', 'Experience with Figma and animation tools', 'Singapore work eligibility']::text[], array['Figma', 'Illustration', 'Animation', 'Game UI']::text[], now() - interval '400 hours', now() + interval '-2 days'),
  ('content-strategist', (select id from public.companies where slug = 'koel-learning'), 'Content Strategist', 'Delhi', 'hybrid', 'full_time', 'mid', 960000, 1380000, 'INR', 'Plan the content that brings learners to our free practice tests: what to write, in which language, and how to tell if it worked.', array['Plan a monthly content calendar in English and Hindi', 'Edit articles written by freelancers', 'Track search traffic and sign-ups per article', 'Update older articles that lost ranking']::text[], array['3+ years in content or SEO', 'Excellent English editing; Hindi a plus', 'Comfortable with analytics tools', 'Interest in education']::text[], array['Content Writing', 'SEO', 'Analytics', 'Editing']::text[], now() - interval '20 hours', now() + interval '23 days'),
  ('customer-success-associate', (select id from public.companies where slug = 'koel-learning'), 'Customer Success Associate', 'Delhi', 'onsite', 'full_time', 'junior', 440000, 620000, 'INR', 'Help learners and parents who call or message with payment, access and course questions, and keep a record of why they are stuck.', array['Reply to learner queries on chat, email and phone', 'Resolve refunds and access issues within policy', 'Log recurring issues for the product team', 'Follow up with learners who stopped logging in']::text[], array['0 to 2 years in customer support', 'Fluent Hindi and English', 'Patient and organised', 'Comfortable with rotating shifts']::text[], array['Communication', 'CRM', 'Zendesk', 'Empathy']::text[], now() - interval '6 hours', now() + interval '13 days'),
  ('android-developer-learning', (select id from public.companies where slug = 'koel-learning'), 'Android Developer', 'Delhi', 'remote', 'full_time', 'mid', 1380000, 2060000, 'INR', 'Own the Android app used by 2 million learners, many on entry-level phones with patchy connections.', array['Build features in Kotlin and Jetpack Compose', 'Make lessons usable offline and resumable', 'Keep app size and startup time down', 'Review code and write instrumented tests']::text[], array['3+ years of Android development', 'Experience with Compose and Kotlin coroutines', 'Understand low-memory device constraints', 'Remote within India']::text[], array['Kotlin', 'Android', 'Jetpack Compose', 'REST APIs', 'Testing']::text[], now() - interval '14 hours', now() + interval '36 days'),
  ('solar-project-engineer', (select id from public.companies where slug = 'greenfield-energy'), 'Solar Project Engineer', 'Coimbatore', 'onsite', 'full_time', 'mid', 840000, 1240000, 'INR', 'Deliver rooftop solar projects from site survey to commissioning for commercial customers, typically 100 kW to 2 MW.', array['Prepare layouts and single-line diagrams', 'Supervise installation crews and contractors', 'Track schedule, cost and safety on each project', 'Handle utility approvals and commissioning']::text[], array['B.E. in Electrical Engineering', '3+ years in solar or electrical projects', 'Proficient in AutoCAD', 'Willing to spend 3 days a week on site']::text[], array['AutoCAD', 'Project Management', 'Electrical Design', 'Site Supervision']::text[], now() - interval '90 hours', now() + interval '29 days'),
  ('graduate-engineer-trainee', (select id from public.companies where slug = 'greenfield-energy'), 'Graduate Engineer Trainee', 'Coimbatore', 'onsite', 'full_time', 'junior', 360000, 480000, 'INR', 'Twelve-month rotation through design, construction and operations, ending with a permanent role in the team that fits best.', array['Rotate across three project teams', 'Assist with design calculations and site measurements', 'Prepare weekly progress reports', 'Complete the internal safety programme']::text[], array['B.E. or B.Tech in Electrical or Mechanical Engineering, 2025 or 2026 batch', 'Minimum 65% aggregate', 'Willingness to relocate across plants', 'Good communication']::text[], array['Electrical Engineering', 'MATLAB', 'Communication']::text[], now() - interval '160 hours', now() + interval '27 days'),
  ('react-native-developer', (select id from public.companies where slug = 'aster-mobility'), 'React Native Developer', 'Gurugram', 'hybrid', 'full_time', 'mid', 1520000, 2240000, 'INR', 'Build the rider app used to unlock scooters, pay and report problems. Reliability on poor networks is the main challenge.', array['Ship features for the iOS and Android rider app', 'Handle offline states and retries gracefully', 'Integrate with scooter Bluetooth and payments', 'Write tests and monitor crash rates']::text[], array['3+ years with React Native', 'Experience shipping to both app stores', 'Strong TypeScript', 'Interest in hardware-connected apps']::text[], array['React Native', 'TypeScript', 'REST APIs', 'Testing']::text[], now() - interval '4 hours', now() + interval '8 days'),
  ('growth-marketing-manager', (select id from public.companies where slug = 'aster-mobility'), 'Growth Marketing Manager', 'Gurugram', 'hybrid', 'full_time', 'senior', 1980000, 2840000, 'INR', 'Own the plan for bringing new riders to the app in 11 cities, with a monthly budget you are accountable for.', array['Plan and run paid and organic acquisition', 'Set up experiments and read the results honestly', 'Work with city teams on local campaigns', 'Report cost per active rider every week']::text[], array['6+ years in performance or growth marketing', 'Comfortable with SQL and attribution', 'Managed budgets above Rs 50 lakh a month', 'Hands-on with Google and Meta ads']::text[], array['SEO', 'Google Ads', 'Analytics', 'Experimentation', 'SQL']::text[], now() - interval '150 hours', now() + interval '21 days'),
  ('ux-designer-healthcare', (select id from public.companies where slug = 'halcyon-design'), 'UX Designer', 'Mumbai', 'hybrid', 'contract', 'mid', 1080000, 1560000, 'INR', 'Six-month contract on a hospital client project redesigning how nurses record observations on a tablet.', array['Observe nurses on the ward and map their workflow', 'Prototype and test with clinical staff', 'Design accessible, high-contrast interfaces', 'Document decisions for the client team']::text[], array['4+ years of UX design', 'Experience researching with non-technical users', 'Strong Figma skills', 'Available for site visits in Mumbai']::text[], array['Figma', 'Prototyping', 'User Research', 'Accessibility']::text[], now() - interval '42 hours', now() + interval '10 days'),
  ('security-analyst-soc', (select id from public.companies where slug = 'northgate-security'), 'Security Analyst, SOC', 'Toronto', 'onsite', 'full_time', 'mid', 82000, 104000, 'CAD', 'Monitor alerts for financial clients, investigate suspicious activity and write incident reports. Rotating shifts in a 24x7 operations centre.', array['Triage and investigate alerts in the SIEM', 'Escalate confirmed incidents with a clear timeline', 'Tune detection rules to reduce false positives', 'Write post-incident reports for clients']::text[], array['2+ years in a SOC or incident response role', 'Understanding of networking and Windows or Linux internals', 'Scripting in Python', 'Authorised to work in Canada']::text[], array['SIEM', 'Incident Response', 'Networking', 'Python']::text[], now() - interval '66 hours', now() + interval '14 days'),
  ('catalogue-operations-executive', (select id from public.companies where slug = 'basil-commerce'), 'Catalogue Operations Executive', 'Kochi', 'onsite', 'full_time', 'junior', 300000, 420000, 'INR', 'List and maintain products from small producers: photos, descriptions, prices and stock, in English and Malayalam.', array['Create and update product listings', 'Check photos and descriptions against quality guidelines', 'Coordinate with producers on stock and pricing', 'Fix listing errors reported by customers']::text[], array['Graduate in any discipline', 'Fluent Malayalam and English', 'Accurate and organised', 'Basic Excel']::text[], array['Excel', 'Data Entry', 'Communication', 'Attention to Detail']::text[], now() - interval '120 hours', now() + interval '-3 days'),
  ('staff-software-engineer', (select id from public.companies where slug = 'vantage-retail'), 'Staff Software Engineer', 'Austin, TX (US remote)', 'remote', 'full_time', 'lead', 178000, 224000, 'USD', 'Set technical direction for the inventory service used by 9,000 stores. Mostly design, review and unblocking other engineers; roughly a third hands-on.', array['Lead design for cross-team changes to inventory and pricing', 'Review architecture proposals and write decision records', 'Mentor senior engineers', 'Stay close to production by joining incident reviews']::text[], array['10+ years of software engineering', 'Led multi-team technical projects', 'Deep experience with Node.js, PostgreSQL and AWS', 'Authorised to work in the US']::text[], array['TypeScript', 'Node.js', 'PostgreSQL', 'System Design', 'AWS']::text[], now() - interval '35 hours', now() + interval '42 days'),
  ('solutions-consultant-part-time', (select id from public.companies where slug = 'vantage-retail'), 'Solutions Consultant (Part-time)', 'Austin, TX', 'hybrid', 'part_time', 'mid', 52000, 68000, 'USD', 'Twenty hours a week helping retail customers configure the point-of-sale software for their stores and run training sessions for store managers.', array['Configure store settings and reports for new customers', 'Run training sessions on site and by video', 'Answer technical questions from sales', 'Capture feedback for the product team']::text[], array['3+ years in retail operations or software implementation', 'Comfortable with SQL and reporting', 'Strong presenter', 'Austin-based; some store visits']::text[], array['Communication', 'SQL', 'Retail Systems', 'Presentation']::text[], now() - interval '10 hours', now() + interval '19 days');
